import numpy as np
import pandas as pd

MU0 = 6.5675
VAR0 = 6.772374686716791

def model(regime, n, seed):
    rng = np.random.default_rng(seed)
    speed = regime.config.get("speed", 1.0)
    mu = MU0  # provisional: ignore speed until experiments identify response
    if VAR0 > MU0 + 1e-9:
        r = MU0**2 / max(VAR0 - MU0, 1e-9)
        p = r / (r + mu)
        y = rng.negative_binomial(r, p, size=n)
    else:
        y = rng.poisson(mu, size=n)
    return pd.DataFrame({"unit_id": np.arange(n), "y": y.astype(int)})

import numpy as np
import pandas as pd

MODEL_KIND = "exp"
LIN = [1.2137857142857136, 5.299761904761903]
EXP = [1.0446364907896528, 0.8215222642880382]
POW = [1.8757574145721227, 0.8030656228125916]

def _mu(speed):
    speed = float(speed)
    if MODEL_KIND == "linear":
        mu = LIN[0] + LIN[1] * speed
    elif MODEL_KIND == "exp":
        mu = float(np.exp(EXP[0] + EXP[1] * speed))
    else:
        mu = float(np.exp(POW[0] + POW[1] * np.log(speed)))
    return max(mu, 1e-9)

def model(regime, n, seed):
    rng = np.random.default_rng(seed)
    speed = regime.config.get("speed", 1.0)
    mu = _mu(speed)
    y = rng.poisson(mu, size=n)
    return pd.DataFrame({"unit_id": np.arange(n), "y": y.astype(int)})

import numpy as np
import pandas as pd

BASE = [1.0646355584735954, 0.8109964391912261]
BEST = "add_quad_excess"
COEF1 = [-0.5137647457798608, 16.71949185557237]
COEF2 = [3.4079832923578017, 3.511635263915993]
COEF3 = [21.137251148535796, 179.9822315229657]

def _mu_base(speed):
    return float(np.exp(BASE[0] + BASE[1] * speed))

def _mu(speed):
    speed = float(speed)
    mb = _mu_base(min(speed, 1.2))
    if speed <= 1.2:
        return max(_mu_base(speed), 1e-9)
    d = speed - 1.2
    if BEST == "add_exp_excess":
        mu = mb + float(np.exp(COEF1[0] + COEF1[1] * d))
    elif BEST == "mult_exp_quad":
        mu = mb * float(np.exp(COEF2[0] * d + COEF2[1] * d * d))
    else:
        mu = mb + COEF3[0] * d + COEF3[1] * d * d
    return max(float(mu), 1e-9)

def model(regime, n, seed):
    rng = np.random.default_rng(seed)
    speed = regime.config.get("speed", 1.0)
    mu = _mu(speed)
    y = rng.poisson(mu, size=n)
    return pd.DataFrame({"unit_id": np.arange(n), "y": y.astype(int)})
